-- Additive bounded source-delta/reconcile APIs; no raw or baseline mutation.
create function operations_private.hub_input_fingerprint_v1(p_sku text,p_source text)
returns text language plpgsql stable set search_path=pg_catalog as $$
declare codes text[]; body jsonb; sellpia_id uuid; trace jsonb;
begin
 if length(coalesce(p_sku,'')) not between 1 and 128 or p_source is null or p_source not in ('','smartstore','makeshop','ably') then raise exception 'invalid fingerprint scope';end if;
 with recursive inputs(sku) as (
  select p_sku union
  select edge.parent_sku from inputs i join operations_private.hub_field_references edge on edge.child_sku=i.sku
 ) select array_agg(sku order by sku) into codes from inputs;
 if cardinality(codes)>2000 then raise exception 'input dependency scope too large';end if;

 if p_source<>'' then
  select array_agg(distinct c.sellpia_sku_code order by c.sellpia_sku_code) into codes
  from operations_private.operations_hub_matrix_export_cache c where c.sellpia_sku_code=any(codes) or
   coalesce(to_jsonb(c)->>(p_source||'_product_code'),'')<>'' and to_jsonb(c)->>(p_source||'_product_code') in
   (select to_jsonb(s)->>(p_source||'_product_code') from operations_private.operations_hub_matrix_export_cache s where s.sellpia_sku_code=any(codes));
 end if;
 if coalesce(cardinality(codes),0)=0 or cardinality(codes)>2000 then raise exception 'fingerprint input unavailable or too large';end if;
 -- Close parent dependencies again after expanding seller siblings.
 with recursive inputs(sku) as (select unnest(codes) union select e.parent_sku from inputs i join operations_private.hub_field_references e on e.child_sku=i.sku)
 select array_agg(sku order by sku) into codes from inputs;
 if cardinality(codes)>2000 then raise exception 'input dependency scope too large';end if;
 with recursive active as (select a.*,r.source_field,r.source_scope,r.input_origin from operations_private.hub_rule_assignments a join operations_private.hub_rules r on r.id=a.rule_id where r.is_active),
 seeds(sku,field,scope) as (
  select s,'calculated_base_price','' from unnest(codes) s
  union select s,f,p_source from unnest(codes) s cross join (values ('platform_registration_price'),('platform_discount_price'),('platform_option_price'),('platform_final_price')) x(f) where p_source<>''
  union select a.sku,a.target_field,'' from active a where a.sku=any(codes) and a.scope='' and p_source=''
 ), nodes(sku,field,scope) as (
  select * from seeds union
  select case when a.input_origin='parent' then ref.parent_sku else n.sku end,
   case when a.rule_id is not null then case when a.input_origin='parent' then ref.source_field else a.source_field end
    when n.field='calculated_base_price' then 'basis_sku_price' else 'actual_inbound_cost' end,
   case when a.rule_id is not null and (case when a.input_origin='parent' then ref.source_field else a.source_field end) like 'platform_%' then coalesce(nullif(ref.source_scope,''),nullif(a.source_scope,''),a.scope) else '' end
  from nodes n left join active a on a.sku=n.sku and a.target_field=n.field and a.scope=n.scope left join operations_private.hub_field_references ref on ref.child_sku=a.sku and ref.rule_id=a.rule_id
  where a.rule_id is not null or n.scope='' and n.field='basis_sku_price' and exists(select 1 from active b where b.sku=n.sku and b.scope='' and b.target_field='actual_inbound_cost')
   or n.scope='' and n.field='calculated_base_price' and exists(select 1 from active b where b.sku=n.sku and b.scope='' and b.target_field in ('actual_inbound_cost','basis_sku_price'))
 ) select jsonb_agg(jsonb_build_object('sku',sku,'field',field,'scope',scope) order by sku,scope,field) into trace from nodes;
 select snapshot_id into sellpia_id from public.sellpia_stock_snapshots where upload_status='ready' order by coalesce(completed_at,created_at) desc,created_at desc,snapshot_id desc limit 1;
 body:=jsonb_build_object('contract','hub-input-v1','source',p_source,'codes',codes,
  'trace',trace,
  'cache',(select coalesce(jsonb_agg(jsonb_build_object('sku',c.sellpia_sku_code,'identity',(select jsonb_object_agg(k,v) from jsonb_each(to_jsonb(c)) kv(k,v) where k like '%\_product_code' escape '\' or k like '%\_option_code' escape '\' or k like '%\_listing_count' escape '\')) order by c.sellpia_sku_code),'[]') from operations_private.operations_hub_matrix_export_cache c where c.sellpia_sku_code=any(codes)),
  'raw',(select coalesce(jsonb_agg(jsonb_build_object('sku',r.sellpia_sku_code,'purchase',case when exists(select 1 from jsonb_array_elements(trace) n where n->>'sku'=r.sellpia_sku_code and n->>'field'='purchase_price') then to_jsonb(r.purchase_price) end,'base',case when exists(select 1 from jsonb_array_elements(trace) n where n->>'sku'=r.sellpia_sku_code and n->>'field'='source_base_price') then r.raw_payload->'base_price' end) order by r.sellpia_sku_code),'[]') from public.sellpia_stock_snapshot_rows r where r.snapshot_id=sellpia_id and r.sellpia_sku_code=any(codes)),
  'master',(select coalesce(jsonb_agg(jsonb_build_object('sku',m.sellpia_sku_code,'base',case when exists(select 1 from jsonb_array_elements(trace) n where n->>'sku'=m.sellpia_sku_code and n->>'field' in ('basis_sku_price','calculated_base_price') and not exists(select 1 from operations_private.hub_rule_assignments a join operations_private.hub_rules ru on ru.id=a.rule_id where a.sku=m.sellpia_sku_code and a.scope='' and ru.is_active)) then to_jsonb(m.base_price) end,'stock',case when exists(select 1 from jsonb_array_elements(trace) n where n->>'sku'=m.sellpia_sku_code and n->>'field' in ('system_stock','calculated_stock')) then to_jsonb(m.stock_quantity) end,'purchase',case when exists(select 1 from jsonb_array_elements(trace) n where n->>'sku'=m.sellpia_sku_code and n->>'field'='purchase_price') then to_jsonb(m.purchase_price) end) order by m.sellpia_sku_code),'[]') from public.operations_hub_sku_operational_master m where m.sellpia_sku_code=any(codes)),
  'inbound',(select coalesce(jsonb_agg(jsonb_build_object('sku',s.sellpia_sku_code,'manual',s.manual_cost,'tag',to_jsonb(t)-'updated_at'-'created_at'-'created_by'-'updated_by') order by s.sellpia_sku_code),'[]') from public.operations_hub_inbound_cost_settings s left join public.operations_hub_inbound_cost_formula_tags t on t.tag_id=s.formula_tag_id where s.sellpia_sku_code=any(codes)),
  'rules',(select coalesce(jsonb_agg(jsonb_build_object('sku',a.sku,'assignment',to_jsonb(a)-'updated_at'-'updated_by','rule',to_jsonb(r)-'updated_at'-'updated_by') order by a.sku,a.scope,a.target_field),'[]') from operations_private.hub_rule_assignments a join operations_private.hub_rules r on r.id=a.rule_id where a.sku=any(codes) and r.is_active),
  'refs',(select coalesce(jsonb_agg(to_jsonb(e) order by e.child_sku,e.scope,e.target_field),'[]') from operations_private.hub_field_references e where e.child_sku=any(codes)),
  'policy',(select coalesce(jsonb_agg(jsonb_build_object('title',d.title,'body',d.body,'version',d.version) order by d.title),'[]') from operations_private.hub_work_documents d where d.kind='formula' and d.title in ('registry-platform:smartstore','registry-platform:makeshop','registry-platform:ably')),
  'drafts',(select coalesce(jsonb_agg(to_jsonb(q)-'updated_at'-'created_at' order by q.change_id),'[]') from public.operations_hub_change_queue q where q.sellpia_sku_code=any(codes) and q.field_key='sellpia_sale_price' and q.status in ('pending','validated','processing')),
  'seller_raw',(select coalesce(jsonb_agg(jsonb_build_object('sku',c.sellpia_sku_code,'source',s.source_channel,'row',to_jsonb(r)-'raw_payload'-'created_at'-'stock'-'snapshot_id') order by c.sellpia_sku_code,s.source_channel,r.product_code,r.option_code),'[]') from operations_private.operations_hub_matrix_export_cache c cross join lateral (select distinct on (source_channel) snapshot_id,source_channel from public.seller_inventory_snapshots where upload_status='ready' order by source_channel,coalesce(completed_at,created_at) desc,created_at desc,snapshot_id desc) s join public.seller_inventory_snapshot_rows r on r.snapshot_id=s.snapshot_id and r.product_code=to_jsonb(c)->>(s.source_channel||'_product_code') and coalesce(r.option_code,'')=coalesce(to_jsonb(c)->>(s.source_channel||'_option_code'),'') where c.sellpia_sku_code=any(codes))
 );
 return encode(extensions.digest(body::text,'sha256'),'hex');
end $$;
revoke all on function operations_private.hub_input_fingerprint_v1(text,text) from public,anon,authenticated;

create function operations_private.hub_input_fingerprints_v1(p_session_token text,p_skus text[],p_source text)
returns jsonb language plpgsql stable security definer set search_path=pg_catalog set statement_timeout='30s' as $$
begin
 perform operations_private.require_operations_hub_operator_session(p_session_token);
 if p_skus is null or cardinality(p_skus) not between 1 and 200 or exists(select 1 from unnest(p_skus) s where length(coalesce(s,'')) not between 1 and 128) then raise exception 'invalid bounded fingerprint request';end if;
 return (select jsonb_object_agg(s,operations_private.hub_input_fingerprint_v1(s,p_source)) from (select distinct unnest(p_skus) s) x);
end $$;
revoke all on function operations_private.hub_input_fingerprints_v1(text,text[],text) from public;
grant execute on function operations_private.hub_input_fingerprints_v1(text,text[],text) to anon,authenticated;
create function public.hub_input_fingerprints_v1(p_session_token text,p_skus text[],p_source text)
returns jsonb language sql security invoker set search_path=pg_catalog as $$select operations_private.hub_input_fingerprints_v1(p_session_token,p_skus,p_source);$$;
revoke all on function public.hub_input_fingerprints_v1(text,text[],text) from public;
grant execute on function public.hub_input_fingerprints_v1(text,text[],text) to anon,authenticated;

create function operations_private.hub_snapshot_facts_v1(p_source text,p_snapshot_id uuid)
returns table(identity text,product_code text,option_code text,facts jsonb) language plpgsql stable set search_path=pg_catalog as $$
begin
 if p_source='sellpia' then
  return query select r.sellpia_sku_code,r.sellpia_product_code,''::text,jsonb_build_object('purchase_price',r.purchase_price,'source_base_price',r.raw_payload->'base_price','stock',r.stock,'available_stock',r.available_stock) from public.sellpia_stock_snapshot_rows r where r.snapshot_id=p_snapshot_id;
 else
  return query select jsonb_build_array(r.product_code,coalesce(r.option_code,''))::text,r.product_code,coalesce(r.option_code,''),jsonb_build_object('stock',r.stock,'price',jsonb_build_object('base',r.base_price,'discounted',r.discounted_base_price,'option',r.option_price,'final',r.final_price,'terms',coalesce(r.discount_terms,'[]'))) from public.seller_inventory_snapshot_rows r where r.snapshot_id=p_snapshot_id;
 end if;
end $$;
revoke all on function operations_private.hub_snapshot_facts_v1(text,uuid) from public,anon,authenticated;

create function operations_private.hub_source_rule_impact_v1(p_skus text[],p_source text,p_before jsonb,p_after jsonb)
returns text[] language sql stable set search_path=pg_catalog as $$
 with recursive active as (
  select a.*,r.source_field,r.source_scope,r.input_origin from operations_private.hub_rule_assignments a join operations_private.hub_rules r on r.id=a.rule_id where r.is_active and a.target_field=r.target_field and a.scope=r.scope
 ), edges as (
  select case when a.input_origin='parent' then f.parent_sku else a.sku end from_sku,case when a.input_origin='parent' then f.source_field else a.source_field end from_field,
   case when a.input_origin='parent' then coalesce(nullif(f.source_scope,''),nullif(a.source_scope,''),case when f.source_field like 'platform_%' then a.scope else '' end) else case when a.source_field like 'platform_%' then coalesce(nullif(a.source_scope,''),a.scope) else '' end end from_scope,
   a.sku to_sku,a.target_field to_field,a.scope to_scope from active a left join operations_private.hub_field_references f on f.child_sku=a.sku and f.rule_id=a.rule_id
  union select a.sku,'actual_inbound_cost','',a.sku,'basis_sku_price','' from active a where a.target_field='actual_inbound_cost' and a.scope='' and not exists(select 1 from active b where b.sku=a.sku and b.scope='' and b.target_field='basis_sku_price')
  union select a.sku,'basis_sku_price','',a.sku,'calculated_base_price','' from active a where a.target_field in ('actual_inbound_cost','basis_sku_price') and a.scope='' and not exists(select 1 from active b where b.sku=a.sku and b.scope='' and b.target_field='calculated_base_price')
 ), seeds(sku,field,scope) as (
  select s,f,'' from unnest(p_skus) s cross join (values ('purchase_price'),('source_base_price'),('system_stock')) x(f) where p_source='sellpia' and
   (f='purchase_price' and p_before->'purchase_price' is distinct from p_after->'purchase_price' or f='source_base_price' and p_before->'source_base_price' is distinct from p_after->'source_base_price' or f='system_stock' and p_before->'stock' is distinct from p_after->'stock')
  union select s,f,p_source from unnest(p_skus) s cross join (values ('platform_registration_price'),('platform_discount_price'),('platform_option_price'),('platform_final_price'),('platform_price')) x(f) where p_source<>'sellpia' and p_before->'price' is distinct from p_after->'price'
 ), flow(sku,field,scope) as (select * from seeds union select e.to_sku,e.to_field,e.to_scope from flow f join edges e on e.from_sku=f.sku and e.from_field=f.field and e.from_scope=f.scope)
 select coalesce(array_agg(distinct a.sku order by a.sku),array[]::text[]) from flow f join active a on a.sku=f.sku and a.target_field=f.field and a.scope=f.scope;
$$;
revoke all on function operations_private.hub_source_rule_impact_v1(text[],text,jsonb,jsonb) from public,anon,authenticated;

create function operations_private.hub_source_delta_page_v1(p_session_token text,p_source text,p_snapshot_id uuid,p_previous_id uuid,p_after text,p_limit integer,p_request_id uuid,p_persist boolean default false)
returns jsonb language plpgsql security definer set search_path=pg_catalog set statement_timeout='30s' set lock_timeout='5s' as $$
declare result jsonb:='[]'; rec record; skus text[]; affected text[]; impact jsonb; changed jsonb; row_id uuid; existing operations_private.hub_source_deltas%rowtype; created timestamptz; previous_created timestamptz; who text;
begin
 who:=operations_private.require_operations_hub_operator_session(p_session_token)->>'username';
 if p_source is null or p_source not in ('sellpia','smartstore','makeshop','ably') or p_snapshot_id is null or p_limit is null or p_limit not between 1 and 200 or length(coalesce(p_after,''))>512 or p_persist is null or p_persist and p_request_id is null then raise exception 'invalid bounded delta request';end if;
 if p_source='sellpia' then
  select created_at into created from public.sellpia_stock_snapshots where snapshot_id=p_snapshot_id and upload_status='ready';
  select created_at into previous_created from public.sellpia_stock_snapshots where snapshot_id=p_previous_id and upload_status='ready';
 else
  select created_at into created from public.seller_inventory_snapshots where snapshot_id=p_snapshot_id and source_channel=p_source and upload_status='ready';
  select created_at into previous_created from public.seller_inventory_snapshots where snapshot_id=p_previous_id and source_channel=p_source and upload_status='ready';
 end if;
 if created is null or p_previous_id is not null and (previous_created is null or previous_created>=created) then raise exception 'invalid snapshot source/order/status';end if;
 if p_persist then perform pg_advisory_xact_lock(hashtextextended('hub-source-delta:'||p_request_id,0));end if;
 for rec in select coalesce(a.identity,b.identity) identity,coalesce(a.product_code,b.product_code) product_code,coalesce(a.option_code,b.option_code) option_code,b.facts before_values,a.facts after_values from operations_private.hub_snapshot_facts_v1(p_source,p_snapshot_id) a full join operations_private.hub_snapshot_facts_v1(p_source,p_previous_id) b using(identity) where a.facts is distinct from b.facts and (p_after is null or coalesce(a.identity,b.identity)>p_after) order by coalesce(a.identity,b.identity) limit p_limit loop
  if p_source='sellpia' then skus:=array[rec.identity];else
   select array_agg(distinct sku order by sku) into skus from (
    select c.sellpia_sku_code sku from operations_private.operations_hub_matrix_export_cache c where to_jsonb(c)->>(p_source||'_product_code')=rec.product_code and coalesce(to_jsonb(c)->>(p_source||'_option_code'),'')=rec.option_code
    union select c.sellpia_sku_code from public.operations_hub_listing_components c join public.operations_hub_seller_listings l on l.listing_id=c.listing_id where c.is_active and l.is_active and l.source_channel=p_source and l.product_code=rec.product_code and coalesce(l.option_code,'')=rec.option_code
    union select m.sellpia_sku_code from public.operations_hub_manual_links m where m.source_channel=p_source and m.product_code=rec.product_code and coalesce(m.option_code,'')=rec.option_code
   ) mapped;
  end if;
  affected:=operations_private.hub_source_rule_impact_v1(skus,p_source,rec.before_values,rec.after_values);
  impact:=jsonb_build_object('affectedSkus',coalesce(affected,array[]::text[]),'mappedSkus',coalesce(skus,array[]::text[]),'identityConflict',coalesce(cardinality(skus),0)>1,'snapshotIdentity',rec.identity,'batchRequest',p_request_id,'operator',who);
  select jsonb_agg(k order by k) into changed from (select jsonb_object_keys(coalesce(rec.before_values,'{}')) k union select jsonb_object_keys(coalesce(rec.after_values,'{}')) k) keys where rec.before_values->k is distinct from rec.after_values->k;
  if p_persist then
   row_id:=md5(p_request_id::text||':'||p_source||':'||rec.identity)::uuid;
   select * into existing from operations_private.hub_source_deltas where request_id=row_id;
   if found then
    if (existing.source,existing.snapshot_id,existing.previous_snapshot_id,existing.before_values,existing.after_values) is distinct from (p_source,p_snapshot_id,p_previous_id,rec.before_values,rec.after_values) then raise exception 'delta request reuse mismatch';end if;
   else
    insert into operations_private.hub_source_deltas(request_id,source,previous_snapshot_id,snapshot_id,identity,before_values,after_values,changed_fields,rule_impact) values(row_id,p_source,p_previous_id,p_snapshot_id,case when cardinality(skus)=1 then skus[1] else rec.identity end,rec.before_values,rec.after_values,changed,impact);
   end if;
  end if;
  result:=result||jsonb_build_array(jsonb_build_object('identity',rec.identity,'product_code',rec.product_code,'option_code',rec.option_code,'before',rec.before_values,'after',rec.after_values,'changedFields',changed,'ruleImpact',impact,'identityChange',case when rec.before_values is null then 'added' when rec.after_values is null then 'deleted' else 'same' end));
 end loop;
 return jsonb_build_object('source',p_source,'snapshot_id',p_snapshot_id,'previous_snapshot_id',p_previous_id,'persisted',p_persist,'rows',result,'next_after',case when jsonb_array_length(result)=p_limit then result->-1->>'identity' end);
end $$;
revoke all on function operations_private.hub_source_delta_page_v1(text,text,uuid,uuid,text,integer,uuid,boolean) from public;
grant execute on function operations_private.hub_source_delta_page_v1(text,text,uuid,uuid,text,integer,uuid,boolean) to anon,authenticated;
create function public.hub_source_delta_page_v1(p_session_token text,p_source text,p_snapshot_id uuid,p_previous_id uuid,p_after text,p_limit integer,p_request_id uuid,p_persist boolean default false)
returns jsonb language sql security invoker set search_path=pg_catalog as $$select operations_private.hub_source_delta_page_v1(p_session_token,p_source,p_snapshot_id,p_previous_id,p_after,p_limit,p_request_id,p_persist);$$;
revoke all on function public.hub_source_delta_page_v1(text,text,uuid,uuid,text,integer,uuid,boolean) from public;
grant execute on function public.hub_source_delta_page_v1(text,text,uuid,uuid,text,integer,uuid,boolean) to anon,authenticated;

create function operations_private.hub_baseline_reconcile_page_v1(p_session_token text,p_source text,p_snapshot_id uuid,p_expected_version_id uuid,p_after text,p_limit integer)
returns jsonb language plpgsql stable security definer set search_path=pg_catalog set statement_timeout='30s' as $$
declare result jsonb; current_id uuid;
begin
 perform operations_private.require_operations_hub_operator_session(p_session_token);
 if p_source is null or p_source not in ('smartstore','makeshop','ably') or p_limit is null or p_limit not between 1 and 200 or length(coalesce(p_after,''))>512 then raise exception 'invalid reconcile scope';end if;
 select current_version_id into current_id from operations_private.hub_baseline_heads where source=p_source;
 if current_id is null or p_expected_version_id is null and p_after is not null or p_expected_version_id is not null and current_id is distinct from p_expected_version_id then raise exception 'stale baseline head';end if;
 if not exists(select 1 from public.seller_inventory_snapshots where snapshot_id=p_snapshot_id and source_channel=p_source and upload_status='ready') then raise exception 'invalid seller snapshot';end if;
 with baseline as (select jsonb_build_array(b.product_code,b.option_code)::text identity,b.product_code,b.option_code,b.facts from operations_private.hub_baseline_rows b where b.version_id=current_id), pairs as (
  select coalesce(n.identity,b.identity) identity,coalesce(n.product_code,b.product_code) product_code,coalesce(n.option_code,b.option_code) option_code,b.facts baseline,n.facts seller from operations_private.hub_snapshot_facts_v1(p_source,p_snapshot_id) n full join baseline b using(identity)
 ), bounded as (select * from pairs where p_after is null or identity>p_after order by identity limit p_limit)
 select coalesce(jsonb_agg(to_jsonb(b)||jsonb_build_object('pending',coalesce((select jsonb_agg(to_jsonb(q)-'created_at'-'updated_at' order by q.field_key) from (select distinct on (field_key) * from public.operations_hub_change_queue where source_channel=p_source and seller_product_code=b.product_code and coalesce(seller_option_code,'')=b.option_code and status in ('pending','validated','processing') and field_key in ('sellpia_sale_price','sellpia_current_stock') order by field_key,updated_at desc,change_id desc) q),'[]')) order by b.identity),'[]') into result from bounded b;
 return jsonb_build_object('source',p_source,'version_id',current_id,'snapshot_id',p_snapshot_id,'rows',result,'next_after',case when jsonb_array_length(result)=p_limit then result->-1->>'identity' end,'preview_only',true);
end $$;
revoke all on function operations_private.hub_baseline_reconcile_page_v1(text,text,uuid,uuid,text,integer) from public;
grant execute on function operations_private.hub_baseline_reconcile_page_v1(text,text,uuid,uuid,text,integer) to anon,authenticated;
create function public.hub_baseline_reconcile_page_v1(p_session_token text,p_source text,p_snapshot_id uuid,p_expected_version_id uuid,p_after text,p_limit integer)
returns jsonb language sql security invoker set search_path=pg_catalog as $$select operations_private.hub_baseline_reconcile_page_v1(p_session_token,p_source,p_snapshot_id,p_expected_version_id,p_after,p_limit);$$;
revoke all on function public.hub_baseline_reconcile_page_v1(text,text,uuid,uuid,text,integer) from public;
grant execute on function public.hub_baseline_reconcile_page_v1(text,text,uuid,uuid,text,integer) to anon,authenticated;
notify pgrst,'reload schema';


CREATE OR REPLACE FUNCTION public.hub_calculation_results_upsert_v1(p_session_token text, p_generation_id bigint, p_rows jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
 SET lock_timeout TO '5s'
AS $function$
declare actor jsonb; run operations_private.hub_calculation_generations%rowtype; received integer; written integer;
begin
 actor:=operations_private.require_operations_hub_operator_session(p_session_token);
 if jsonb_typeof(p_rows) is distinct from 'array' then raise exception '계산 결과 rows는 배열이어야 합니다.';end if;
 received:=jsonb_array_length(p_rows);
 if received not between 1 and 1000 or pg_column_size(p_rows)>2097152 then raise exception '계산 결과는 요청당 1~1,000개, 최대 2MB입니다.';end if;
 if exists(select 1 from jsonb_array_elements(p_rows) x where jsonb_typeof(x) is distinct from 'object') then raise exception '계산 결과 항목 형식 오류';end if;
 if exists(select 1 from jsonb_array_elements(p_rows) x cross join lateral jsonb_object_keys(x) k where k not in ('sku','scope','field','value','status','error','rule_versions','result_details')) then raise exception '계산 결과에 규칙 설정 또는 지원하지 않는 항목을 저장할 수 없습니다.';end if;
 if exists(select 1 from jsonb_array_elements(p_rows) x where x ? 'result_details' and jsonb_typeof(x->'result_details') is distinct from 'object') then raise exception 'result_details는 객체여야 합니다.';end if;
 if exists(select 1 from jsonb_array_elements(p_rows) x cross join lateral jsonb_object_keys(coalesce(x->'result_details','{}')) k where k not in ('discount_terms','input_fingerprint')) then raise exception 'result_details에는 discount_terms와 input_fingerprint만 저장할 수 있습니다.';end if;
 if exists(select 1 from jsonb_array_elements(p_rows) x where x->'result_details' ? 'input_fingerprint' and (coalesce(x->'result_details'->>'input_fingerprint','') !~ '^[0-9a-f]{64}$' or x->'result_details'->>'input_fingerprint' is distinct from operations_private.hub_input_fingerprint_v1(x->>'sku',coalesce(x->>'scope','')))) then raise exception 'calculation input fingerprint changed or invalid';end if;
 if exists(select 1 from jsonb_array_elements(p_rows) x where x->'result_details' ? 'discount_terms' and jsonb_typeof(x->'result_details'->'discount_terms') is distinct from 'array') then raise exception 'discount_terms는 배열이어야 합니다.';end if;
 if exists(select 1 from jsonb_array_elements(p_rows) x where jsonb_array_length(coalesce(x->'result_details'->'discount_terms','[]'))>16) then raise exception '할인 조건은 최대 16개입니다.';end if;
 if exists(select 1 from jsonb_array_elements(p_rows) x cross join lateral jsonb_array_elements(coalesce(x->'result_details'->'discount_terms','[]')) t where jsonb_typeof(t) is distinct from 'object') then raise exception '할인 조건 항목은 객체여야 합니다.';end if;
 if exists(select 1 from jsonb_array_elements(p_rows) x where x ? 'rule_versions' and jsonb_typeof(x->'rule_versions') is distinct from 'array') then raise exception 'rule_versions는 배열이어야 합니다.';end if;
 if exists(select 1 from jsonb_array_elements(p_rows) x cross join lateral jsonb_array_elements(coalesce(x->'rule_versions','[]')) v
   where jsonb_typeof(v) is distinct from 'object') then raise exception '규칙 버전 항목 형식 오류';end if;
 if exists(select 1 from jsonb_array_elements(p_rows) x cross join lateral jsonb_array_elements(coalesce(x->'rule_versions','[]')) v
   where coalesce(v->>'id','') !~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$'
    or coalesce(v->>'version','') !~ '^[1-9][0-9]{0,8}$'
    or (v ? 'assignmentVersion' and coalesce(v->>'assignmentVersion','') !~ '^[1-9][0-9]{0,8}$')
    or exists(select 1 from jsonb_object_keys(v) k where k not in ('id','version','assignmentVersion'))) then raise exception '규칙 버전 메타데이터 오류';end if;
 if exists(select 1 from jsonb_to_recordset(p_rows) x(sku text,scope text,field text) group by sku,coalesce(scope,''),field having count(*)>1) then raise exception '같은 SKU·판매처·필드가 요청 안에서 중복되었습니다.';end if;
 -- Serialize retries for one generation; different generations can compute in parallel.
 select * into run from operations_private.hub_calculation_generations where generation_id=p_generation_id for update;
 if not found or run.created_by is distinct from actor->>'username' then raise exception '유효한 계산 작업이 필요합니다.';end if;
 if exists(select 1 from jsonb_to_recordset(p_rows) x(sku text,scope text,field text,value numeric,status text,error text,rule_versions jsonb,result_details jsonb)
   join operations_private.hub_calculated_results r on r.sku=x.sku and r.scope=coalesce(x.scope,'') and r.field=x.field
   where r.generation_id=p_generation_id and (r.value,r.status,r.error,r.rule_versions,r.result_details) is distinct from (x.value,coalesce(x.status,'calculated'),x.error,coalesce(x.rule_versions,'[]'::jsonb),coalesce(x.result_details,'{}'::jsonb))) then raise exception '같은 계산 작업의 결과를 다른 값으로 재사용할 수 없습니다.';end if;
 insert into operations_private.hub_calculated_results as stored(sku,scope,field,value,status,error,rule_versions,result_details,generation_id,calculated_at)
 select x.sku,coalesce(x.scope,''),x.field,x.value,coalesce(x.status,'calculated'),x.error,coalesce(x.rule_versions,'[]'),coalesce(x.result_details,'{}'),run.generation_id,run.calculated_at
 from jsonb_to_recordset(p_rows) x(sku text,scope text,field text,value numeric,status text,error text,rule_versions jsonb,result_details jsonb)
 order by x.sku,coalesce(x.scope,''),x.field
 on conflict(sku,scope,field) do update set value=excluded.value,status=excluded.status,error=excluded.error,rule_versions=excluded.rule_versions,result_details=excluded.result_details,generation_id=excluded.generation_id,calculated_at=excluded.calculated_at
 where stored.generation_id<excluded.generation_id;
 get diagnostics written=row_count;
 return jsonb_build_object('generation_id',run.generation_id,'received',received,'upserted',written,'unchanged_or_older',received-written);
end $function$
;
alter function public.hub_calculation_results_upsert_v1(text,bigint,jsonb) set statement_timeout='60s';
CREATE OR REPLACE FUNCTION operations_private.hub_canary_operations_v1(p_source text, p_version_id uuid, p_operations jsonb, p_serialized boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'pg_catalog'
AS $function$
declare op jsonb; facts jsonb; target jsonb; k text; v_sku text; original jsonb; links jsonb;
begin
 if jsonb_typeof(p_operations) is distinct from 'array' or jsonb_array_length(p_operations)>100 or pg_column_size(p_operations)>262144 then raise exception 'invalid operation set';end if;
 if exists(select 1 from jsonb_array_elements(p_operations) x group by x->>'product_code',coalesce(x->>'option_code',''),x->>'field' having count(*)>1) then raise exception 'duplicate operation identity/field';end if;
 for op in select value from jsonb_array_elements(p_operations) loop
  v_sku:=op->>'sku';
  if v_sku is null or not(v_sku in ('5566-1','5566-2','5566-3','5566-4') or v_sku ~ '^1181-([1-9]|[12][0-9]|3[01])$') then raise exception 'outside finite canary scope';end if;
  if op->>'disposition' is distinct from 'CHANGE' or coalesce(op->>'provenance','') not in ('manual','calculated','baseline') or coalesce(op->>'field','') not in ('price','stock') or not op?'carrier_before' or not op?'baseline_before' or not op?'effective_target' then raise exception 'invalid operation contract';end if;
  if op->>'field'='price' and op->>'provenance'='baseline' then raise exception 'Rule-less baseline price cannot mutate carrier';end if;
  if op->>'field'='price' and op->>'provenance'='calculated' and (op->>'freshness' is distinct from 'fresh' or op->>'generation_id' is null) then raise exception 'inactive/stale calculated price';end if;
  if op->>'provenance'='manual' and op->>'override_id' is null then raise exception 'explicit override identity required';end if;
  -- Mutable identity/Rule/draft proof is checked at registration and frozen in the immutable plan.
  if not p_serialized then
  if op->>'provenance'='manual' and not exists(select 1 from public.operations_hub_change_queue q where q.change_id::text=op->>'override_id' and q.sellpia_sku_code=v_sku and q.source_channel=p_source and q.seller_product_code=op->>'product_code' and coalesce(q.seller_option_code,'')=coalesce(op->>'option_code','') and q.status in ('pending','validated','processing') and (
   (op->>'field'='stock' and q.field_key='sellpia_current_stock' and q.after_value=op->'effective_target') or
   (op->>'field'='price' and q.field_key='sellpia_sale_price' and (q.base_price_source='manual' or q.option_price_source='manual' or q.pricing_input_mode='final' or q.base_price_source='discount' and exists(select 1 from jsonb_array_elements(coalesce(q.price_discount_terms_after,'[]'::jsonb)) t where t->>'input_source'='manual')) and jsonb_build_object('base',q.price_base_after,'discounted',q.price_discounted_base_after,'option',q.price_option_after,'final',q.price_final_after,'terms',coalesce(q.price_discount_terms_after,'[]'::jsonb))=op->'effective_target')
  )) then raise exception 'explicit active override/target not verified';end if;
  select coalesce(jsonb_agg(z),'[]'::jsonb) into links from (
   select distinct l.product_code,coalesce(l.option_code,'') option_code from public.operations_hub_listing_components c join public.operations_hub_seller_listings l on l.listing_id=c.listing_id where c.is_active and l.is_active and c.sellpia_sku_code=v_sku and l.source_channel=p_source
   union select m.product_code,coalesce(m.option_code,'') from public.operations_hub_manual_links m where m.sellpia_sku_code=v_sku and m.source_channel=p_source
   union select to_jsonb(c)->>(p_source||'_product_code'),coalesce(to_jsonb(c)->>(p_source||'_option_code'),'') from operations_private.operations_hub_matrix_export_cache c where c.sellpia_sku_code=v_sku and coalesce(to_jsonb(c)->>(p_source||'_product_code'),'')<>''
  ) z;
  if jsonb_array_length(links)<>1 or links->0->>'product_code' is distinct from op->>'product_code' or links->0->>'option_code' is distinct from coalesce(op->>'option_code','') then raise exception 'canary identity missing/conflict';end if;
  if op->>'field'='price' and op->>'provenance'='calculated' and not exists(
   select 1 from operations_private.hub_calculated_results cr where cr.sku=v_sku and cr.scope=p_source and cr.field='platform_final_price' and cr.status='calculated' and cr.error is null and cr.generation_id::text=op->>'generation_id'
   and cr.value=(op->'effective_target'->>'final')::numeric
   and coalesce(cr.result_details->'discount_terms','[]'::jsonb)=op->'effective_target'->'terms'
   and operations_private.hub_input_fingerprint_v1(v_sku,p_source)=op->>'current_input_fingerprint'
   and coalesce(cr.result_details->>'input_fingerprint','')<>'' and cr.result_details->>'input_fingerprint'=op->>'current_input_fingerprint'
   and exists(select 1 from operations_private.hub_rule_assignments a join operations_private.hub_rules r on r.id=a.rule_id where a.sku=v_sku and a.scope=p_source and r.is_active and r.scope=a.scope and r.target_field=a.target_field and a.target_field in ('platform_registration_price','platform_discount_price','platform_option_price'))
   and not exists(select 1 from jsonb_array_elements(cr.rule_versions) rv where not exists(select 1 from operations_private.hub_rule_assignments a join operations_private.hub_rules r on r.id=a.rule_id where a.sku=v_sku and a.scope=p_source and r.is_active and r.scope=a.scope and r.target_field=a.target_field and r.id::text=rv->>'id' and r.version::text=rv->>'version' and a.version::text=rv->>'assignmentVersion'))
   and not exists(select 1 from (values ('platform_registration_price','base'),('platform_discount_price','discounted'),('platform_option_price','option')) f(field,key) where not exists(select 1 from operations_private.hub_calculated_results part where part.sku=v_sku and part.scope=p_source and part.field=f.field and part.status='calculated' and part.error is null and part.generation_id=cr.generation_id and part.value=(op->'effective_target'->>f.key)::numeric and not exists(select 1 from jsonb_array_elements(part.rule_versions) rv where not exists(select 1 from operations_private.hub_rule_assignments a join operations_private.hub_rules r on r.id=a.rule_id where a.sku=v_sku and a.scope=p_source and r.is_active and r.scope=a.scope and r.target_field=a.target_field and r.id::text=rv->>'id' and r.version::text=rv->>'version' and a.version::text=rv->>'assignmentVersion'))))
  ) then raise exception 'active calculated generation/fingerprint not verified';end if;
  end if;
  select b.facts into facts from operations_private.hub_baseline_rows b where b.version_id=p_version_id and b.product_code=op->>'product_code' and b.option_code=coalesce(op->>'option_code','');
  if not found then raise exception 'baseline unavailable';end if;
  original:=facts->(op->>'field');target:=op->'effective_target';
  if original is null or original='null'::jsonb or original is distinct from op->'baseline_before' then raise exception 'baseline before mismatch';end if;
  if op->>'provenance'='baseline' and target is distinct from original then raise exception 'baseline provenance target mismatch';end if;
  if op->'carrier_before' is null or op->'carrier_before'='null'::jsonb then raise exception 'carrier before unavailable';end if;
  if p_serialized and target is distinct from op->'serialized_after' then raise exception 'serialized after/target mismatch';end if;
  if op->>'field'='stock' then
   if jsonb_typeof(target) is distinct from 'number' then raise exception 'stock must be integer';end if;
   if target::text::numeric<0 or target::text::numeric<>trunc(target::text::numeric) or target::text::numeric>9007199254740991 then raise exception 'stock out of range';end if;
  else
   if jsonb_typeof(target) is distinct from 'object' or jsonb_typeof(target->'terms') is distinct from 'array' then raise exception 'price tuple incomplete';end if;
   foreach k in array array['base','discounted','option','final'] loop
    if jsonb_typeof(target->k) is distinct from 'number' then raise exception 'price component missing';end if;
    if (target->>k)::numeric<>trunc((target->>k)::numeric) or abs((target->>k)::numeric)>9007199254740991 or (k<>'option' and (target->>k)::numeric<0) then raise exception 'price out of range';end if;
   end loop;
   if (target->>'discounted')::numeric+(target->>'option')::numeric<>(target->>'final')::numeric then raise exception 'price tuple inconsistent';end if;
  end if;
 end loop;
 return coalesce((select jsonb_agg(x-'serialized_after' order by x->>'product_code',coalesce(x->>'option_code',''),x->>'field') from jsonb_array_elements(p_operations) x),'[]'::jsonb);
end $function$
;
CREATE OR REPLACE FUNCTION operations_private.hub_matrix_shadow_payload_v1(p_source text, p_rows jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'pg_catalog'
 SET statement_timeout TO '15s'
AS $function$
declare vid uuid; sid uuid; version_no integer; result jsonb;
begin
 if p_source is null or p_source not in ('smartstore','makeshop','ably') or jsonb_typeof(p_rows) is distinct from 'array' or jsonb_array_length(p_rows) not between 1 and 200 or pg_column_size(p_rows)>262144 then raise exception 'invalid bounded shadow scope';end if;
 if exists(select 1 from jsonb_array_elements(p_rows) x where length(coalesce(x->>'sku','')) not between 1 and 128 or length(coalesce(x->>'product_code',''))>128 or length(coalesce(x->>'option_code',''))>128 or length(coalesce(x->'carrier'->>'seller_product_code',''))>128 or length(coalesce(x->'carrier'->>'full_option_label',''))>2048) then raise exception 'invalid shadow identity';end if;
 if exists(select 1 from jsonb_array_elements(p_rows) x group by x->>'sku' having count(*)>1) then raise exception 'duplicate shadow SKU';end if;
 select h.current_version_id,v.source_snapshot_id,v.version into vid,sid,version_no from operations_private.hub_baseline_heads h join operations_private.hub_baseline_versions v on v.id=h.current_version_id where h.source=p_source and h.mode='shadow';
 if sid is null then
  with recursive ancestry as (select id,previous_version_id,source_snapshot_id from operations_private.hub_baseline_versions where id=vid union all select v.id,v.previous_version_id,v.source_snapshot_id from operations_private.hub_baseline_versions v join ancestry a on v.id=a.previous_version_id) select source_snapshot_id into sid from ancestry where source_snapshot_id is not null limit 1;
 end if;
 select jsonb_agg(jsonb_build_object('sku',x->>'sku','product_code',x->>'product_code','option_code',coalesce(x->>'option_code',''),
  'baseline',b.facts,'snapshot',case when r.product_code is null then null else jsonb_build_object('stock',r.stock,'price',jsonb_build_object('base',r.base_price,'discounted',r.discounted_base_price,'option',r.option_price,'final',r.final_price,'terms',coalesce(r.discount_terms,'[]'::jsonb))) end,
  'candidates',coalesce((select jsonb_agg(jsonb_build_object('product_code',br.product_code,'option_code',br.option_code,'option_name',sr.option_name,'facts',br.facts,'source_row_no',br.source_row_no)) from operations_private.hub_baseline_rows br join public.seller_inventory_snapshot_rows sr on sr.snapshot_id=sid and sr.product_code=br.product_code and coalesce(sr.option_code,'')=br.option_code where br.version_id=vid and br.product_code=x->'carrier'->>'seller_product_code' and sr.option_name=x->'carrier'->>'full_option_label'),'[]'::jsonb),
  'declared_links',coalesce((select jsonb_agg(z) from (select distinct c.sellpia_sku_code sku,l.product_code,coalesce(l.option_code,'') option_code from public.operations_hub_listing_components c join public.operations_hub_seller_listings l on l.listing_id=c.listing_id where c.is_active and l.is_active and l.source_channel=p_source and c.sellpia_sku_code=x->>'sku' union select m.sellpia_sku_code,m.product_code,coalesce(m.option_code,'') from public.operations_hub_manual_links m where m.source_channel=p_source and m.sellpia_sku_code=x->>'sku' union select ca.sellpia_sku_code,to_jsonb(ca)->>(p_source||'_product_code'),coalesce(to_jsonb(ca)->>(p_source||'_option_code'),'') from operations_private.operations_hub_matrix_export_cache ca where ca.sellpia_sku_code=x->>'sku' and coalesce(to_jsonb(ca)->>(p_source||'_product_code'),'')<>'') z),'[]'::jsonb),
  'current_rules',coalesce((select jsonb_agg(jsonb_build_object('id',ru.id,'version',ru.version,'assignmentVersion',a.version,'name',ru.name)) from operations_private.hub_rule_assignments a join operations_private.hub_rules ru on ru.id=a.rule_id where a.sku=x->>'sku' and ru.is_active and a.scope in ('',p_source)),'[]'::jsonb),
  'calculated',coalesce((select jsonb_agg(to_jsonb(cr)) from operations_private.hub_calculated_results cr where cr.sku=x->>'sku' and cr.scope in ('',p_source)),'[]'::jsonb),
  'draft_markers',coalesce((select jsonb_agg(jsonb_build_object('change_id',q.change_id,'base_price_source',q.base_price_source,'option_price_source',q.option_price_source,'pricing_input_mode',q.pricing_input_mode)) from public.operations_hub_change_queue q where q.sellpia_sku_code=x->>'sku' and q.source_channel=p_source and q.status in ('pending','validated','processing','failed')),'[]'::jsonb),
  'source_delta',(select jsonb_build_object('before',d.before_values,'after',d.after_values,'changedFields',d.changed_fields,'ruleImpact',d.rule_impact,'changed',true,'created_at',d.created_at) from operations_private.hub_source_deltas d where ((d.source in ('sellpia',p_source) and d.identity=x->>'sku') or d.rule_impact->'affectedSkus' ? (x->>'sku')) order by d.created_at desc limit 1)
 ) order by x->>'sku') into result
 from jsonb_array_elements(p_rows) x left join operations_private.hub_baseline_rows b on b.version_id=vid and b.product_code=x->>'product_code' and b.option_code=coalesce(x->>'option_code','') left join public.seller_inventory_snapshot_rows r on r.snapshot_id=sid and r.product_code=b.product_code and coalesce(r.option_code,'')=b.option_code;
 return jsonb_build_object('source',p_source,'mode','shadow','version_id',vid,'version',version_no,'snapshot_id',sid,'rows',coalesce(result,'[]'::jsonb));
end $function$
;
create index hub_source_deltas_identity_time_idx on operations_private.hub_source_deltas(identity,created_at desc);
create index hub_source_deltas_impact_idx on operations_private.hub_source_deltas using gin ((rule_impact->'affectedSkus'));
notify pgrst,'reload schema';
